 [InitializeOnLoad] public static class RealmwalkerR2 {
  const string Root="Assets/Realmwalker",Prefab=Root+"/Realmwalker_Player.prefab";static IEnumerator routine;static double deadline;static int checks;static bool errors;static Keyboard keyboard;static InputSettings.BackgroundBehavior oldBackground;static InputSettings.EditorInputBehaviorInPlayMode oldEditorInput;
  static RealmwalkerR2(){EditorApplication.playModeStateChanged+=State;}
  [MenuItem("Tools/Lost Worlds/R2/Setup Jungle Runner")]
  public static void Setup(){if(EditorApplication.isPlayingOrWillChangePlaymode||!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;
   var model=PrefabUtility.LoadPrefabContents(Prefab);try{if(model.GetComponent<Rigidbody>()!=null)throw new Exception("Unexpected Rigidbody");var cc=model.GetComponent<CharacterController>();if(cc==null)cc=model.AddComponent<CharacterController>();cc.height=1.85f;cc.center=new Vector3(0,.925f,0);cc.radius=.32f;cc.skinWidth=.025f;cc.stepOffset=.18f;cc.slopeLimit=45;cc.minMoveDistance=0;if(model.GetComponent<RealmwalkerRunner>()==null)model.AddComponent<RealmwalkerRunner>();PrefabUtility.SaveAsPrefabAsset(model,Prefab);}finally{PrefabUtility.UnloadPrefabContents(model);}
   var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Root+"/Rig/RealmwalkerAnimator.controller");foreach(var n in new[]{"ForwardSpeed","LateralSpeed","VerticalSpeed","Grounded","Paused"})if(!controller.parameters.Any(p=>p.name==n))controller.AddParameter(n,n=="Grounded"||n=="Paused"?AnimatorControllerParameterType.Bool:AnimatorControllerParameterType.Float);EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();
   var scene=EditorSceneManager.OpenScene(IntegrationSession.RealmScenes[0]);var existing=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<RealmwalkerRunner>(true)).SingleOrDefault();var go=existing!=null?existing.gameObject:(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Prefab));var realmRoot=scene.GetRootGameObjects().Single(r=>r.GetComponentInChildren<RealmBindings>()!=null);go.transform.SetParent(realmRoot.transform,true);go.transform.position=new Vector3(0,.08f,2);go.transform.rotation=Quaternion.identity;PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);EditorSceneManager.SaveScene(scene);Debug.Log("R2 SETUP: Jungle +Z, 8m road, lanes -2/0/+2, CC radius .32/height1.85, speed configurable, jump1.35/gravity22. No realm geometry edits.");}
  [MenuItem("Tools/Lost Worlds/R2/Play Jungle Runner")]
  public static void Play(){if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;EditorSceneManager.OpenScene(IntegrationSession.RealmScenes[0]);EditorApplication.isPlaying=true;}
  static Transform[] poseBones; static Vector3[] posePositions; static Quaternion[] poseRotations;
  static void CheckStandingPose(){if(poseBones==null)return;if(poseBones.Length>0&&poseBones[0]!=null&&poseBones[0].GetComponentInParent<RealmwalkerAnimation>()!=null)return;for(int i=0;i<poseBones.Length;i++)if(poseBones[i]!=null&&(Vector3.Distance(poseBones[i].localPosition,posePositions[i])>.001f||Quaternion.Angle(poseBones[i].localRotation,poseRotations[i])>.1f))throw new Exception("R2 posture drift: "+poseBones[i].name);}
  public static void BatchPolish()=>EditorApplication.delayCall+=Tests;
  public static void DiagnosePose(){var go=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Prefab));var a=go.GetComponent<Animator>();var ts=go.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("RW_")).ToArray();var pos=ts.Select(t=>t.localPosition).ToArray();var rot=ts.Select(t=>t.localRotation).ToArray();a.Rebind();a.Update(.1f);for(int i=0;i<ts.Length;i++)if(Vector3.Distance(pos[i],ts[i].localPosition)>.001f||Quaternion.Angle(rot[i],ts[i].localRotation)>1)Debug.Log("R2 POSE "+ts[i].name+" position "+pos[i]+" -> "+ts[i].localPosition+" rotation delta "+Quaternion.Angle(rot[i],ts[i].localRotation));Object.DestroyImmediate(go);EditorApplication.Exit(0);}
  public static void Batch()=>EditorApplication.delayCall+=()=>{try{Setup();SessionState.SetBool("R2.pending",true);EditorApplication.isPlaying=true;}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}};
  [MenuItem("Tools/Lost Worlds/R2/Run Focused Movement Checks")]
  public static void Tests(){if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;EditorSceneManager.OpenScene(IntegrationSession.RealmScenes[0]);SessionState.SetBool("R2.pending",true);EditorApplication.isPlaying=true;}
  public static void BatchEndpoint(){SessionState.SetBool("R2.endpoint",true);Batch();}
  static void State(PlayModeStateChange s){if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("R2.pending",false)){SessionState.SetBool("R2.pending",false);checks=0;errors=false;oldBackground=InputSystem.settings.backgroundBehavior;oldEditorInput=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;Application.logMessageReceived+=Log;routine=Run();deadline=EditorApplication.timeSinceStartup+120;EditorApplication.update+=Tick;}if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("R2.done",false)){SessionState.SetBool("R2.done",false);if(Application.isBatchMode)EditorApplication.Exit(SessionState.GetBool("R2.pass",false)?0:1);}}
  static void Log(string m,string stack,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert||t==LogType.Warning)errors=true;}
  static void Tick(){try{CheckStandingPose();RealmwalkerR3Validation.Observe();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("R2 timeout");if(routine.MoveNext())return;RealmwalkerR3Validation.Finish();Check(!errors,"No runtime errors/warnings");End(true);}catch(Exception e){Debug.LogException(e);End(false);}}
  static void End(bool ok){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;InputSystem.settings.backgroundBehavior=oldBackground;InputSystem.settings.editorInputBehaviorInPlayMode=oldEditorInput;if(keyboard!=null){InputSystem.RemoveDevice(keyboard);keyboard=null;}SessionState.SetBool("R2.pass",ok);SessionState.SetBool("R2.done",true);Debug.Log("R2 RESULT: "+checks+" checks; passed="+ok);EditorApplication.isPlaying=false;}
  static void Check(bool ok,string label){if(!ok)throw new Exception("R2 FAIL: "+label);checks++;Debug.Log("R2 PASS: "+label);}
  static IEnumerator Wait(float seconds){float end=Time.time+seconds;while(Time.time<end)yield return null;}
  static IEnumerator Key(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));InputSystem.Update();IntegrationSession.Instance.GetComponent<HardwareCommandSimulator>().PollKeyboard();InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();yield return null;}
  static IEnumerator Run(){while(IntegrationSession.Instance==null||IntegrationSession.Instance.CurrentRealm==null)yield return null;var s=IntegrationSession.Instance;s.SetInputMode(GameplayInputMode.Simulator);var r=Object.FindAnyObjectByType<RealmwalkerRunner>();var gate=Object.FindAnyObjectByType<PortalUnlockMechanism>();var adapter=s.GetComponentInChildren<ProcessedHardwareAdapter>(true);keyboard=InputSystem.AddDevice<Keyboard>();var w=Wait(.3f);while(w.MoveNext())yield return null;
   if(SessionState.GetBool("R4.hardware",false)){SessionState.SetBool("R4.hardware",false);var hardware=RealmwalkerR4Validation.Hardware(r,s,gate);while(hardware.MoveNext())yield return null;yield break;}
   if(SessionState.GetBool("R4.pending",false)){SessionState.SetBool("R4.pending",false);var extra=RealmwalkerR4Validation.Run(r,s,gate);while(extra.MoveNext())yield return null;}
   float z=0,end=0;if(!SessionState.GetBool("R2.endpoint",false)){var rest=AssetDatabase.LoadAssetAtPath<GameObject>(Prefab).GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("RW_")).ToArray();poseBones=rest.Select(t=>r.GetComponentsInChildren<Transform>().Single(b=>b.name==t.name)).ToArray();posePositions=rest.Select(t=>t.localPosition).ToArray();poseRotations=rest.Select(t=>t.localRotation).ToArray();CheckStandingPose();RealmwalkerR3Validation.Begin(r);Check(r.GetComponent<RealmwalkerAnimation>()!=null||!r.GetComponent<Animator>().enabled,"Animated R3 pose or preserved R2 rest pose");Check(r.GetComponentsInChildren<SkinnedMeshRenderer>().All(m=>m.sharedMesh!=null&&m.bones.All(b=>b!=null)&&m.sharedMaterials.All(v=>v!=null)),"Skin, bone and material references intact");Check(r!=null&&s.PlayerReference==r.transform&&r.Grounded,"Runner bound and grounded in actual Jungle Play Mode");Check(r.GetComponent<Rigidbody>()==null&&r.GetComponents<CharacterController>().Length==1,"Single CharacterController; no Rigidbody");Check(r.GetComponent<Animator>().avatar.isHuman,"R1 Humanoid preserved");z=r.transform.position.z;w=Wait(.5f);while(w.MoveNext())yield return null;Check(Mathf.Abs((r.transform.position.z-z)/.5f-3.1f)<.3f,"Measured auto forward speed approximately 3.1 m/s");s.Channel.Send(HardwareCommand.ACTIVATE);Check(!gate.CanExit,"Remote ACTIVATE cannot unlock from start");
   w=Key(UnityEngine.InputSystem.Key.A);while(w.MoveNext())yield return null;w=Wait(.4f);while(w.MoveNext())yield return null;Check(r.Lane==-1&&Mathf.Abs(r.transform.position.x+2)<.05f,"P9 keyboard LEFT reaches left position (lane="+r.Lane+", x="+r.transform.position.x+")");for(int i=0;i<10;i++)s.Channel.Send(HardwareCommand.LEFT);w=Wait(.2f);while(w.MoveNext())yield return null;Check(r.Lane==-1&&r.transform.position.x>=-2.01f,"Repeated LEFT clamps at road edge");
   w=Key(UnityEngine.InputSystem.Key.D);while(w.MoveNext())yield return null;w=Wait(.4f);while(w.MoveNext())yield return null;Check(r.Lane==0&&Mathf.Abs(r.transform.position.x)<.05f,"P9 RIGHT moves exactly one position");Check(adapter.ReceiveMessage("{\"command\":\"RIGHT\"}"),"P10 parser forwards RIGHT");w=Wait(.4f);while(w.MoveNext())yield return null;Check(r.Lane==1&&Mathf.Abs(r.transform.position.x-2)<.05f,"Hardware RIGHT reaches right position");for(int i=0;i<8;i++)s.Channel.Send(HardwareCommand.RIGHT);Check(r.Lane==1,"Repeated RIGHT clamped");
   s.AutoRunPause.RequestPause(r);z=r.transform.position.z;w=Wait(.35f);while(w.MoveNext())yield return null;Check(Mathf.Abs(r.transform.position.z-z)<.01f&&r.Paused,"Pause bridge stops immediately");s.AutoRunPause.ReleasePause(r);
   r.ResetMotion(new Vector3(0,.08f,8));w=Wait(.2f);while(w.MoveNext())yield return null;int jumps=r.AcceptedJumps;s.Channel.Send(HardwareCommand.JUMP);float peak=0;end=Time.time+1.1f;while(Time.time<end){peak=Mathf.Max(peak,r.transform.position.y);if(Time.time<end-.6f)s.Channel.Send(HardwareCommand.JUMP);yield return null;}Check(r.AcceptedJumps==jumps+1&&peak>1.1f,"Jump height and double-jump prevention");Check(r.Grounded,"Gravity returns to ground");
   r.ResetMotion(new Vector3(0,.08f,14.3f));w=Wait(1);while(w.MoveNext())yield return null;Check(r.transform.position.z<15.9f,"Low step offset does not climb jump log");s.Channel.Send(HardwareCommand.JUMP);w=Wait(1.2f);while(w.MoveNext())yield return null;Check(r.transform.position.z>18&&r.Grounded,"Jump clears physical log and lands");
   Check(!Physics.Raycast(new Vector3(0,5,72),Vector3.down,20,~0,QueryTriggerInteraction.Ignore),"Bridge gap has no invisible floor");r.ResetMotion(new Vector3(0,2.12f,71));w=Wait(.15f);while(w.MoveNext())yield return null;Check(adapter.ReceiveMessage("{\"command\":\"JUMP\"}"),"P10 JUMP accepted");w=Wait(1.3f);while(w.MoveNext())yield return null;Check(r.transform.position.z>74&&r.Grounded&&Mathf.Abs(r.transform.position.y-2.1f)<.12f,"CharacterController physically jumps real bridge gap and lands");
   r.ResetMotion(new Vector3(0,2.1f,72));r.SetAutoRunPaused(true);w=Wait(.35f);while(w.MoveNext())yield return null;Check(!r.Grounded&&r.transform.position.y<1.3f,"Gap loses grounded state and gravity continues while paused");w=Wait(1);while(w.MoveNext())yield return null;Check(s.IsRecovering&&!s.CommandsReady,"Missed jump starts guarded current-realm recovery");while(s.IsRecovering||s.PlayerReference==null)yield return null;r=s.PlayerReference.GetComponent<RealmwalkerRunner>();gate=Object.FindAnyObjectByType<PortalUnlockMechanism>();adapter=s.GetComponent<ProcessedHardwareAdapter>();Check(s.CurrentRealm.RealmIndex==0&&r.transform.position.z<5,"Missed Jungle jump reloads its safe start");r.SetAutoRunPaused(false);
   }SessionState.SetBool("R2.endpoint",false);var box=gate.GetComponent<BoxCollider>();float approachX=gate.WithinActivationRange(new Vector3(0,gate.transform.position.y,gate.transform.position.z))?0:2;float start=approachX==0?box.bounds.min.z-1:gate.transform.position.z-3;var ground=gate.transform.root.Find("Environment/Terrain_Ground/JungleGround").GetComponent<Collider>();ground.Raycast(new Ray(new Vector3(approachX,30,start),Vector3.down),out var hit,60);r.ResetMotion(new Vector3(approachX,hit.point.y+.08f,start));w=Wait(2);while(w.MoveNext())yield return null;Check(r.Paused&&!gate.CanExit&&!s.IsTransitioning,"Endpoint waits without activating or transitioning");z=r.transform.position.z;w=Wait(.5f);while(w.MoveNext())yield return null;Check(Mathf.Abs(r.transform.position.z-z)<.01f,"Lever wait remains stationary");w=Key(UnityEngine.InputSystem.Key.E);while(w.MoveNext())yield return null;w=Wait(1.1f);while(w.MoveNext())yield return null;Check(gate.RevealComplete&&!r.Paused,"P9 E unlocks and resumes after reveal");end=Time.time+4;while(r.transform.position.z<101f&&Time.time<end)yield return null;s.Channel.Send(HardwareCommand.JUMP);end=Time.time+6;while(s.CurrentRealm.RealmIndex==0&&Time.time<end)yield return null;Check(s.CurrentRealm.RealmIndex==1&&r==null,"Actual portal entry transitions to Ruins; previous realm runner removed: realm="+s.CurrentRealm.RealmIndex+", runner="+(r==null?"destroyed":r.transform.position+" paused="+r.Paused)+", error="+s.LastError);
  }
 }
